-- =========================================================
-- ASTEL DATABASE SCHEMA (COMBINED)
-- Target: MySQL / MariaDB
-- UUID: VARCHAR(36) generated by UUID()
-- =========================================================
CREATE DATABASE IF NOT EXISTS db_stack_underflow;

USE db_stack_underflow;

-- =========================================================
-- 1. USERS & PROFILES MODULE
-- =========================================================

CREATE TABLE IF NOT EXISTS users (
        id VARCHAR(36) NOT NULL DEFAULT (UUID()),
        username VARCHAR(100) NOT NULL,
        password VARCHAR(150) NOT NULL,
        email VARCHAR(100) NOT NULL UNIQUE,
        is_active BOOLEAN NOT NULL DEFAULT TRUE,
        created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,

        PRIMARY KEY (id),
        UNIQUE KEY uq_users_username (username),
        UNIQUE KEY uq_users_email (email)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Belom create
CREATE TABLE IF NOT EXISTS profiles (
    id VARCHAR(36) NOT NULL DEFAULT (UUID()),
    user_id VARCHAR(36) NOT NULL,
    full_name VARCHAR(100) NOT NULL,
    bio VARCHAR(150) NULL,
    photo_profile_url VARCHAR(150) NULL,
    photo_profile_public_id VARCHAR(100) NULL,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,

    PRIMARY KEY (id),
    UNIQUE KEY uq_profiles_user_id (user_id),

    CONSTRAINT fk_profiles_user
        FOREIGN KEY (user_id) REFERENCES users(id)
        ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS profile_social_medias (
    id VARCHAR(36) NOT NULL DEFAULT (UUID()),
    user_id VARCHAR(36) NOT NULL,
    platform VARCHAR(50) NOT NULL,
    url VARCHAR(100) NOT NULL,

    PRIMARY KEY (id),
    KEY idx_social_media_user (user_id),

    CONSTRAINT fk_social_media_user
        FOREIGN KEY (user_id) REFERENCES users(id)
        ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS skills (
    id VARCHAR(36) NOT NULL DEFAULT (UUID()),
    skill_name VARCHAR(100) NOT NULL,
    scope ENUM('system', 'private') NOT NULL DEFAULT 'system',
    created_by VARCHAR(36) NULL,

    PRIMARY KEY (id),
    KEY idx_skills_name (skill_name),
    KEY idx_skills_scope (scope),
    KEY idx_skills_created_by (created_by),

    CONSTRAINT fk_skills_created_by
        FOREIGN KEY (created_by) REFERENCES users(id)
        ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS user_skill (
    id VARCHAR(36) NOT NULL DEFAULT (UUID()),
    skill_id VARCHAR(36) NOT NULL,
    user_id VARCHAR(36) NOT NULL,

    PRIMARY KEY (id),
    UNIQUE KEY uq_user_skill (user_id, skill_id),
    KEY idx_user_skill_skill_id (skill_id),
    KEY idx_user_skill_user_id (user_id),

    CONSTRAINT fk_user_skill_skill
        FOREIGN KEY (skill_id) REFERENCES skills(id)
        ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT fk_user_skill_user
        FOREIGN KEY (user_id) REFERENCES users(id)
        ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- =========================================================
-- =========================================================
-- 2. FEEDS MODULE
-- =========================================================

CREATE TABLE IF NOT EXISTS public_posts (
    id VARCHAR(36) NOT NULL DEFAULT (UUID()),
    user_id VARCHAR(36) NOT NULL,
    title VARCHAR(150) NOT NULL,
    description TEXT NOT NULL,
    portfolio_type ENUM('link', 'images') NOT NULL DEFAULT 'link',
    external_url VARCHAR(255) NULL,
    view_count INT NOT NULL DEFAULT 0,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,

    PRIMARY KEY (id),
    KEY idx_public_posts_user_id (user_id),

    CONSTRAINT fk_posts_user 
        FOREIGN KEY (user_id) REFERENCES users (id) 
        ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS media_posts (
    id VARCHAR(36) NOT NULL DEFAULT (UUID()),
    post_id VARCHAR(36) NOT NULL,
    media_url VARCHAR(255) NOT NULL,
    media_public_id VARCHAR(150) NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,

    PRIMARY KEY (id),
    KEY idx_media_posts_post_id (post_id),

    CONSTRAINT fk_media_post 
        FOREIGN KEY (post_id) REFERENCES public_posts (id) 
        ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS like_posts (
    id VARCHAR(36) NOT NULL DEFAULT (UUID()),
    post_id VARCHAR(36) NOT NULL,
    user_id VARCHAR(36) NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,

    PRIMARY KEY (id),
    UNIQUE KEY uq_user_post_like (user_id, post_id),
    KEY idx_like_posts_post_id (post_id),
    KEY idx_like_posts_user_id (user_id),

    CONSTRAINT fk_likes_post 
        FOREIGN KEY (post_id) REFERENCES public_posts (id) 
        ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT fk_likes_user 
        FOREIGN KEY (user_id) REFERENCES users (id) 
        ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS comments (
    id VARCHAR(36) NOT NULL DEFAULT (UUID()),
    user_id VARCHAR(36) NOT NULL,
    post_id VARCHAR(36) NOT NULL,
    content TEXT NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,

    PRIMARY KEY (id),
    KEY idx_comments_post_id (post_id),
    KEY idx_comments_user_id (user_id),

    CONSTRAINT fk_comments_user 
        FOREIGN KEY (user_id) REFERENCES users (id) 
        ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT fk_comments_post 
        FOREIGN KEY (post_id) REFERENCES public_posts (id) 
        ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- =========================================================
-- 3. COLLABORATION MODULE
-- =========================================================

CREATE TABLE IF NOT EXISTS collaborations (
    id VARCHAR(36) NOT NULL DEFAULT (UUID()),
    user_id VARCHAR(36) NOT NULL,
    title VARCHAR(255) NOT NULL,
    description TEXT NOT NULL,
    `type` ENUM('coursework', 'portfolio', 'product') NOT NULL DEFAULT 'coursework',
    required_member INT NOT NULL DEFAULT 1,
    due_date DATE NULL,
    communication_url VARCHAR(255) NULL,
    status ENUM('open', 'in-progress', 'completed') NOT NULL DEFAULT 'open',
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,

    PRIMARY KEY (id),
    KEY idx_collaborations_user_id (user_id),
    KEY idx_collaborations_status (status),
    KEY idx_collaborations_created_at (created_at),

    CONSTRAINT fk_collaborations_user
        FOREIGN KEY (user_id) REFERENCES users(id)
        ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS collab_media (
    id VARCHAR(36) NOT NULL DEFAULT (UUID()),
    collab_id VARCHAR(36) NOT NULL,
    media_url VARCHAR(255) NOT NULL,
    media_public_id VARCHAR(255) NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,

    PRIMARY KEY (id),
    KEY idx_collab_media_collab_id (collab_id),

    CONSTRAINT fk_collab_media_collab
        FOREIGN KEY (collab_id) REFERENCES collaborations(id)
        ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS collab_skills (
    id VARCHAR(36) NOT NULL DEFAULT (UUID()),
    collab_id VARCHAR(36) NOT NULL,
    skill_id VARCHAR(36) NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,

    PRIMARY KEY (id),
    UNIQUE KEY uq_collab_skills (collab_id, skill_id),
    KEY idx_collab_skills_collab_id (collab_id),
    KEY idx_collab_skills_skill_id (skill_id),

    CONSTRAINT fk_collab_skills_collab
        FOREIGN KEY (collab_id) REFERENCES collaborations(id)
        ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT fk_collab_skills_skill
        FOREIGN KEY (skill_id) REFERENCES skills(id)
        ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS collaboration_applications (
    id VARCHAR(36) NOT NULL DEFAULT (UUID()),
    user_id VARCHAR(36) NOT NULL,
    collab_id VARCHAR(36) NOT NULL,
    message TEXT NULL,
    status ENUM('pending', 'accepted', 'rejected') NOT NULL DEFAULT 'pending',
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,

    PRIMARY KEY (id),
    UNIQUE KEY uq_collab_application (user_id, collab_id),
    KEY idx_collab_app_user_id (user_id),
    KEY idx_collab_app_collab_id (collab_id),
    KEY idx_collab_app_status (status),

    CONSTRAINT fk_collab_app_user
        FOREIGN KEY (user_id) REFERENCES users(id)
        ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT fk_collab_app_collab
        FOREIGN KEY (collab_id) REFERENCES collaborations(id)
        ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- =========================================================
-- 4. CHANNEL & MESSAGING MODULE
-- =========================================================

CREATE TABLE IF NOT EXISTS user_collaboration (
    id VARCHAR(36) NOT NULL DEFAULT (UUID()),
    user_id VARCHAR(36) NOT NULL,
    collaboration_id VARCHAR(36) NOT NULL,
    status ENUM('not-started', 'pending', 'complete', 'revise') NOT NULL DEFAULT 'not-started',
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,

    PRIMARY KEY (id),
    UNIQUE KEY uq_user_collaboration (user_id, collaboration_id),
    KEY idx_user_collab_user_id (user_id),
    KEY idx_user_collab_collab_id (collaboration_id),

    CONSTRAINT fk_user_collab_user
        FOREIGN KEY (user_id) REFERENCES users(id)
        ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT fk_user_collab_collab
        FOREIGN KEY (collaboration_id) REFERENCES collaborations(id)
        ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS circle (
    id VARCHAR(36) NOT NULL DEFAULT (UUID()),
    collaboration_id VARCHAR(36) NOT NULL,
    title VARCHAR(255) NOT NULL,
    photo_profile_url VARCHAR(255) NULL DEFAULT NULL,
    timestamp DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,

    PRIMARY KEY (id),
    UNIQUE KEY uq_circle_collaboration_id (collaboration_id),
    KEY idx_circle_collaboration_id (collaboration_id),

    CONSTRAINT fk_circle_collaboration
        FOREIGN KEY (collaboration_id) REFERENCES collaborations(id)
        ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS zone (
    id VARCHAR(36) NOT NULL DEFAULT (UUID()),
    circle_id VARCHAR(36) NOT NULL,
    title VARCHAR(150) NOT NULL,
    allow_public_message BOOLEAN NOT NULL DEFAULT FALSE,
    timestamp DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,

    PRIMARY KEY (id),
    KEY idx_zone_circle_id (circle_id),

    CONSTRAINT fk_zone_circle
        FOREIGN KEY (circle_id) REFERENCES circle(id)
        ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS zone_messages (
    id VARCHAR(36) NOT NULL DEFAULT (UUID()),
    zone_id VARCHAR(36) NOT NULL,
    user_id VARCHAR(36) NOT NULL,
    message TEXT NOT NULL,
    timestamp DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,

    PRIMARY KEY (id),
    KEY idx_zone_messages_zone_id (zone_id),
    KEY idx_zone_messages_user_id (user_id),
    KEY idx_zone_messages_timestamp (timestamp),

    CONSTRAINT fk_zone_messages_zone
        FOREIGN KEY (zone_id) REFERENCES zone(id)
        ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT fk_zone_messages_user
        FOREIGN KEY (user_id) REFERENCES users(id)
        ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- =========================================================
-- 5. NOTIFICATIONS & DIRECT MESSAGES MODULE
-- (added 2026-11-10 — the frontend needs these; the original
-- schema had neither a notifications table nor a DM table)
-- =========================================================

CREATE TABLE IF NOT EXISTS notifications (
    id VARCHAR(36) NOT NULL DEFAULT (UUID()),
    user_id VARCHAR(36) NOT NULL,
    actor_id VARCHAR(36) NULL,
    `type` VARCHAR(50) NOT NULL,
    title VARCHAR(255) NOT NULL,
    body TEXT NULL,
    target_type VARCHAR(50) NULL,
    target_id VARCHAR(36) NULL,
    is_read BOOLEAN NOT NULL DEFAULT FALSE,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,

    PRIMARY KEY (id),
    KEY idx_notifications_user_id (user_id),
    KEY idx_notifications_is_read (is_read),
    KEY idx_notifications_created_at (created_at),

    CONSTRAINT fk_notifications_user
        FOREIGN KEY (user_id) REFERENCES users(id)
        ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT fk_notifications_actor
        FOREIGN KEY (actor_id) REFERENCES users(id)
        ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS dm_conversations (
    id VARCHAR(36) NOT NULL DEFAULT (UUID()),
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,

    PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS dm_participants (
    id VARCHAR(36) NOT NULL DEFAULT (UUID()),
    conversation_id VARCHAR(36) NOT NULL,
    user_id VARCHAR(36) NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,

    PRIMARY KEY (id),
    UNIQUE KEY uq_dm_participant (conversation_id, user_id),
    KEY idx_dm_participants_conversation_id (conversation_id),
    KEY idx_dm_participants_user_id (user_id),

    CONSTRAINT fk_dm_participants_conversation
        FOREIGN KEY (conversation_id) REFERENCES dm_conversations(id)
        ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT fk_dm_participants_user
        FOREIGN KEY (user_id) REFERENCES users(id)
        ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS dm_messages (
    id VARCHAR(36) NOT NULL DEFAULT (UUID()),
    conversation_id VARCHAR(36) NOT NULL,
    sender_id VARCHAR(36) NOT NULL,
    body TEXT NOT NULL,
    is_read BOOLEAN NOT NULL DEFAULT FALSE,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,

    PRIMARY KEY (id),
    KEY idx_dm_messages_conversation_id (conversation_id),
    KEY idx_dm_messages_sender_id (sender_id),
    KEY idx_dm_messages_created_at (created_at),

    CONSTRAINT fk_dm_messages_conversation
        FOREIGN KEY (conversation_id) REFERENCES dm_conversations(id)
        ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT fk_dm_messages_sender
        FOREIGN KEY (sender_id) REFERENCES users(id)
        ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
